    this.setState({ zoomOpen1: true, scale1: 1, offsetX1: 0, offsetY1: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusClose1));
  };
  closeZoom1 = () => {
    this.setState({ zoomOpen1: false });
    requestAnimationFrame(() => requestAnimationFrame(this.focusTrigger1));
  };
  zoomIn1 = () => this.setState(s => ({ scale1: Math.min(4, Math.round((s.scale1 + 0.5) * 10) / 10) }));
  zoomOut1 = () => this.setState(s => {
    const next = Math.max(1, Math.round((s.scale1 - 0.5) * 10) / 10);
    return { scale1: next, offsetX1: next === 1 ? 0 : s.offsetX1, offsetY1: next === 1 ? 0 : s.offsetY1 };
  });
  onWheel1 = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scale1 + delta) * 100) / 100));
      return { scale1: next, offsetX1: next === 1 ? 0 : s.offsetX1, offsetY1: next === 1 ? 0 : s.offsetY1 };
    });
  };
  onPointerDown1 = (e) => {
